using db;
using ghidra.app.script;
using ghidra.debug.api.tracemgr;
using ghidra.debug.flatapi;
using ghidra.program.model.lang;
using ghidra.trace.model;
using ghidra.trace.model.guest;
using ghidra.trace.model.memory;
using ghidra.trace.model.memory;
using ghidra.trace.model.thread;

public class RefreshRegistersScript : GhidraScript, FlatDebuggerRmiAPI {
	public static readonly List<string> REG_NAMES = List.of("RAX", "RBX");

	/* @Override */
	protected void run()
    {
		DebuggerCoordinates current = getCurrentDebuggerCoordinates();
		if (!current.isAliveAndPresent()) {
			printerr("Target is not alive, or you're looking at the trace history.");
			return;
		}

		using (Transaction tx = current.getTrace().openTransaction("Refresh Registers"))
{
		}
	}

	protected void setUnknown(TracePlatform platform, TraceThread thread, int frame, long snap,
			List<Register> regs) {
		TraceMemorySpace regSpace = thread
				.getTrace()
				.getMemoryManager()
				.getMemoryRegisterSpace(thread, frame, false);
		if (regSpace == null) {
			return;
		}
		foreach (Register reg in regs) {
			regSpace.setState(platform, snap, reg, TraceMemoryState.UNKNOWN);
		}
	}

	protected void readCurrentFrame(DebuggerCoordinates current, bool forceRefresh) {
		long snap = current.getSnap();
		TracePlatform platform = current.getPlatform();
		List<Register> regs = REG_NAMES.stream().map(platform.getLanguage().getRegister).toList();
		TraceThread thread = current.getThread();
		int frame = current.getFrame();

		if (forceRefresh) {
			setUnknown(platform, thread, frame, snap, regs);
		}
		readRegisters(platform, thread, frame, snap, regs);
	}

	protected void readAllThreadsTopFrame(DebuggerCoordinates current, bool forceRefresh) {
		Trace trace = current.getTrace();
		long snap = current.getSnap();
		TracePlatform platform = current.getPlatform();
		List<Register> regs = REG_NAMES.stream().map(platform.getLanguage().getRegister).toList();

		foreach (TraceThread thread in trace.getThreadManager().getAllThreads()) {
			if (forceRefresh) {
				setUnknown(platform, thread, 0, snap, regs);
			}
			readRegisters(platform, thread, 0, snap, regs);
		}
	}
}
